mapper.select:

/* selectUserPivot - Lee JiSeob */
{CALL SA_SP_SELECT_USER_PIVOT2 (
    #{pivotStr, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{searchField, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{searchValue, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{searchValue2, mode=IN, jdbcType=VARCHAR, javaType=String},
    #{resultList, mode=OUT, jdbcType=CURSOR, javaType=ResultSet, resultMap=testUser}
)
}

/* selectUserPivot - Lee JiSeob */
WITH T (USER_ID2, USER_ID, USER_NAME, MENU_ID_PIVOT, RIGHT_EXISTS) AS ( SELECT D.USER_ID AS USER_ID2, D.USER_ID, E.FLNM_ENCPT || ' (' || D.USER_ID || ')' AS USER_NAME, C.MENU_NO AS MENU_ID_PIVOT, CASE WHEN C.USER_ID IS NULL THEN 'N' ELSE 'Y' END AS RIGHT_EXISTS FROM SCA300 E /* 개인정보 */ JOIN USER_INFO D ON D.PERSONAL_ID_NUM = E.PERSONAL_ID_NUM LEFT JOIN RIGHT_USER C ON C.USER_ID = D.USER_ID
WHERE D.USER_ID like '%' || #{searchValue} || '%'
WHERE E.USER_NAME like '%' || #{searchValue} || '%'
) SELECT * FROM T PIVOT ( MAX(RIGHT_EXISTS) FOR MENU_ID_PIVOT IN ( #{pivotStr} ) )

/* selectUserAuthList - Lee JiSeob */ SELECT B.USER_ID, c.FLNM_ENCPT FROM saa200 B, sca100 C WHERE b.ENFSN_NO = c.ENFSN_NO AND B.JOIN_APRV_YN = 'Y' AND NVL(B.USE_BGNG_YMD, '10000101') <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND NVL(B.USE_END_YMD, '99991230') >= TO_CHAR(SYSDATE, 'YYYYMMDD')
AND B.USER_ID like '%' || #{searchValue} || '%'
AND C.FLNM_ENCPT = #{searchValue}

/* selectAuthrtList - Kang.Hwa.Young */ SELECT A.AUTHRT_ID, A.AUTHRT_NM FROM SAB400 A WHERE A.DEL_YN = 'N'
AND A.AUTHRT_NM like '%' || #{searchValue} || '%'
ORDER BY A.SRTNG_SQNCE
